      impact: violation.impact,
      targets: violation.nodes.map((node) => node.target)
    }));

  const output = {
    collapsedWcag: summarize(collapsedResult),
    expandedWcag: summarize(expandedResult),
    disclosureState,
    escapeClosesFocusedDisclosure: keyboardResult
  };
  console.log(JSON.stringify(output, null, 2));

  const stateOk = disclosureState.length === 6 && disclosureState.every((item) => item.expanded === 'false' && item.hidden && item.controls && item.classOk);
  process.exit(output.collapsedWcag.length || output.expandedWcag.length || !stateOk || !keyboardResult ? 1 : 0);
})().catch((error) => {
  console.error(error.stack || error.message);
  process.exit(1);
});
